begin read only; select jsonb_build_object('automatic_rls_definition',pg_get_functiondef('public.rls_auto_enable()'::regprocedure),'automatic_rls_acl',(select proacl::text from pg_proc where oid='public.rls_auto_enable()'::regprocedure),'default_acl',(select jsonb_agg(jsonb_build_object('role',pg_get_userbyid(defaclrole),'schema',defaclnamespace::regnamespace::text,'object_type',defaclobjtype,'acl',defaclacl::text)) from pg_default_acl),'managed_triggers',(select jsonb_agg(pg_get_triggerdef(t.oid) order by t.tgname) from pg_trigger t where t.tgrelid in ('storage.objects'::regclass,'storage.buckets'::regclass) and not t.tgisinternal),'storage_migrations',(select jsonb_agg(to_jsonb(m) order by id) from storage.migrations m),'auth_migration_versions',(select jsonb_agg(version order by version) from auth.schema_migrations),'auth_user_count',(select count(*) from auth.users),'object_columns',(select jsonb_agg(jsonb_build_object('name',column_name,'type',data_type,'nullable',is_nullable) order by ordinal_position) from information_schema.columns where table_schema='storage' and table_name='objects')) as audit; rollback;
